WITH shared_records AS MATERIALIZED (SELECT id, name, type, deleted_at, created_at FROM records), shared_links AS MATERIALIZED (SELECT source_id, target_id, relationship FROM links WHERE relationship IN ('addressed_to', 'reply_to')), shared_events AS MATERIALIZED (SELECT record_id, local_seq, actor, run_key, type FROM content_events WHERE record_id IN (SELECT id FROM shared_records WHERE type = 'Message' AND deleted_at IS NULL)), message_meta AS MATERIALIZED (SELECT record_id, MIN(local_seq) AS first_seq, SUM(CASE WHEN type = 'message.reaction.added.v1' THEN 1 WHEN type = 'message.reaction.removed.v1' THEN -1 ELSE 0 END) AS reactions FROM shared_events GROUP BY record_id), message_senders AS MATERIALIZED (SELECT e.record_id, e.actor, e.run_key, g.reactions FROM message_meta g JOIN shared_events e ON e.local_seq = g.first_seq), awaiting_messages AS MATERIALIZED (SELECT message_id FROM messages_awaiting_reply) SELECT m.id, m.name, substr(b.body, 1, 360) AS preview, m.created_at, b.home_id AS home_id, s.actor AS actor, s.run_key AS run_key, (SELECT f.value FROM facet_values f WHERE f.record_id = m.id AND f.key = 'expectation') AS expectation, (SELECT l.target_id FROM shared_links l WHERE l.source_id = m.id AND l.relationship = 'addressed_to' ORDER BY l.target_id LIMIT 1) AS to_id, (SELECT p.name FROM shared_links l JOIN shared_records p ON p.id = l.target_id WHERE l.source_id = m.id AND l.relationship = 'addressed_to' ORDER BY p.id LIMIT 1) AS to_name, (SELECT l.target_id FROM shared_links l WHERE l.source_id = m.id AND l.relationship = 'reply_to' ORDER BY l.target_id LIMIT 1) AS reply_to_id, (SELECT COUNT(*) FROM awaiting_messages w WHERE w.message_id = m.id) AS awaiting, COALESCE(s.reactions, 0) AS reactions, CASE WHEN s.actor IN (SELECT b.identifier FROM bindings b WHERE b.system = 'account') THEN 1 ELSE 0 END AS from_viewer, CASE WHEN EXISTS (SELECT 1 FROM shared_links l JOIN bindings b ON b.record_id = l.target_id AND b.system = 'account' WHERE l.source_id = m.id AND l.relationship = 'addressed_to') THEN 1 ELSE 0 END AS to_viewer FROM shared_records m JOIN records b ON b.id = m.id LEFT JOIN message_senders s ON s.record_id = m.id WHERE m.type = 'Message' AND m.deleted_at IS NULL AND (s.actor IN (SELECT b.identifier FROM bindings b WHERE b.system = 'account') OR EXISTS (SELECT 1 FROM shared_links l JOIN bindings b ON b.record_id = l.target_id AND b.system = 'account' WHERE l.source_id = m.id AND l.relationship = 'addressed_to')) ORDER BY m.created_at DESC, m.id LIMIT 200
